t.script:
document.addEventListener("DOMContentLoaded", function() {
    function highlightMenu() {
        var currentPath = window.location.pathname;
        var currentHash = window.location.hash;
        var links = document.querySelectorAll('.vb-sidebar .nav-link, .offcanvas .nav-link');

        // ค้นหาลิงก์ที่ตรงกันมากที่สุด (Best Match) เพื่อป้องกันการไฮไลต์ซ้ำสองเมนูพร้อมกัน
        var bestMatchLink = null;
        var maxMatchLength = -1;

        links.forEach(function(link) {
            var href = link.getAttribute('href');
            if (href) {
                // รีเซ็ตสถานะ active เดิมให้เป็นสีปกติ
                link.classList.remove('active', 'text-white');
                link.classList.add('text-white-50');

                var isMatch = false;
                if (href.indexOf('#') !== -1) {
                    // สำหรับลิงก์ที่มี hash (เช่น เมนูย่อย /automotive/repair#repair_history)
                    isMatch = (currentPath + currentHash === href);
                } else {
                    // สำหรับลิงก์ปกติ
                    var hasSubmenuActive = false;
                    if (currentHash) {
                        hasSubmenuActive = document.querySelector('[href="' + currentPath + currentHash + '"]') !== null;
                    }
                    isMatch = (currentPath === href) && !hasSubmenuActive;
                }

                // หากมีเงื่อนไขตรงกัน 100% ให้บันทึกเป็นตัวเลือกที่ดีที่สุด
                if (isMatch) {
                    bestMatchLink = link;
                    maxMatchLength = href.length;
                } else if (href !== '/automotive' && href.indexOf('#') === -1 && currentPath.startsWith(href)) {
                    // หากเป็นการแมตช์ด้วย startsWith ให้เปรียบเทียบความยาวของ path เพื่อเลือกตัวที่จำเพาะเจาะจงที่สุด
                    if (href.length > maxMatchLength) {
                        bestMatchLink = link;
                        maxMatchLength = href.length;
                    }
                }
            }
        });

        // กำหนดคลาส active ให้กับปุ่มนำทางที่ตรงกันมากที่สุดเพียงตัวเดียว
        if (bestMatchLink) {
            bestMatchLink.classList.remove('text-white-50');
            bestMatchLink.classList.add('active', 'text-white');
        }
    }
    highlightMenu();
    // ตรวจจับการเปลี่ยน hash เมื่อผู้ใช้คลิกเลื่อนส่วนในหน้าเดียวกัน
    window.addEventListener('hashchange', highlightMenu);
});

form.script:
document.addEventListener('DOMContentLoaded', function() {
    const typeFilter = document.getElementById('vehicle_type_filter');
    const vehicleSelect = document.getElementById('vehicle_id');
    const galleryContainer = document.getElementById('vehicle_gallery_container');
    const galleryItems = document.querySelectorAll('.vehicle-gallery-item');
    const allOptions = Array.from(vehicleSelect.options).slice(1);

    typeFilter.addEventListener('change', function() {
        const selectedType = this.value;

        // 1. Update Dropdown
        vehicleSelect.innerHTML = '-- กรุณาเลือกรถ --';
        if (!selectedType) {
            vehicleSelect.disabled = true;
            galleryContainer.classList.add('d-none');
            return;
        }

        let found = false;
        allOptions.forEach(opt => {
            if (opt.getAttribute('data-type') === selectedType) {
                vehicleSelect.appendChild(opt);
                found = true;
            }
        });
        vehicleSelect.disabled = !found;

        // 2. Update Gallery
        galleryContainer.classList.remove('d-none');
        galleryItems.forEach(item => {
            item.style.display = (item.getAttribute('data-type') === selectedType) ? 'block' : 'none';
        });
    });
});

div.script:
(function() {
    function pad(n) { return n.toString().padStart(2, '0'); }
    function formatDisplay(d) {
        return d.getDate() + '/' + pad(d.getMonth()+1) + '/' + d.getFullYear() +
               ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
    }
    function formatInput(d) {
        return d.getFullYear() + '-' + pad(d.getMonth()+1) + '-' + pad(d.getDate()) +
               'T' + pad(d.getHours()) + ':' + pad(d.getMinutes());
    }

    var now = new Date();

    // set hidden field
    var ds = document.getElementById('date_start');
    if (ds) ds.value = formatInput(now);

    // set display label
    var disp_s = document.getElementById('display_start');
    if (disp_s) disp_s.textContent = formatDisplay(now);
})();

document.addEventListener('DOMContentLoaded', function() {
    const editBtns = document.querySelectorAll('.edit-vehicle-btn');
    const editModalFieldId = document.getElementById('edit_vehicle_id');
    const editModalFieldPlate = document.getElementById('edit_license_plate');
    const editModalFieldModel = document.getElementById('edit_model_name');

    editBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            if (editModalFieldId) editModalFieldId.value = this.dataset.id;
            if (editModalFieldPlate) editModalFieldPlate.value = this.dataset.license_plate;
            if (editModalFieldModel) editModalFieldModel.value = this.dataset.model_name;
        });
    });

    // Transfer Modal Data Filling
    const transferBtns = document.querySelectorAll('.transfer-vehicle-btn');
    const transModalId = document.getElementById('transfer_vehicle_id');
    const transModalName = document.getElementById('transfer_vehicle_name');
    const transModalFrom = document.getElementById('transfer_from_factory');

    transferBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            if (transModalId) transModalId.value = this.dataset.id;
            if (transModalName) transModalName.textContent = this.dataset.name;
            if (transModalFrom) transModalFrom.textContent = this.dataset.factory;
        });
    });
});

t.script:
document.addEventListener('DOMContentLoaded', function() {
    const typeFilter = document.getElementById('repair_type_filter');
    const vehicleSelect = document.getElementById('repair_vehicle_id');

    if (typeFilter && vehicleSelect) {
        const allOptions = Array.from(vehicleSelect.options).slice(1);
        typeFilter.addEventListener('change', function() {
            const selectedType = this.value;
            vehicleSelect.innerHTML = '-- เลือกคัน --';

            if (!selectedType) {
                vehicleSelect.disabled = true;
                return;
            }

            let count = 0;
            allOptions.forEach(opt => {
                if (opt.getAttribute('data-type') === selectedType) {
                    vehicleSelect.appendChild(opt.cloneNode(true));
                    count++;
                }
            });
            vehicleSelect.disabled = count === 0;
        });
    }
});

                document.addEventListener('DOMContentLoaded', function() {
                    const finishRepairModal = document.getElementById('finishRepairModal');
                    if (finishRepairModal) {
                        finishRepairModal.addEventListener('show.bs.modal', function (event) {
                            const button = event.relatedTarget;
                            const repairId = button.getAttribute('data-id');
                            const vehicleName = button.getAttribute('data-name');
                            const autoPartsJsonStr = button.getAttribute('data-parts-json');
                            const autoPartsCost = parseFloat(button.getAttribute('data-parts-cost') || 0);

                            const modalIdInput = finishRepairModal.querySelector('#modal_repair_id');
                            const modalVehicleName = finishRepairModal.querySelector('#modal_vehicle_name');
                            const modalDeletedMovementIds = finishRepairModal.querySelector('#modal_deleted_movement_ids');
                            const modalRepairCost = finishRepairModal.querySelector('input[name="repair_cost"]');
                            const modalPartsUsedTextarea = finishRepairModal.querySelector('textarea[name="parts_used"]');

                            if (modalIdInput) modalIdInput.value = repairId;
                            if (modalVehicleName) modalVehicleName.textContent = vehicleName;
                            if (modalDeletedMovementIds) modalDeletedMovementIds.value = '';
                            if (modalPartsUsedTextarea) modalPartsUsedTextarea.value = '';
                            // ตัวแปรราคาปัจจุบันที่แสดงใน Modal
                            let currentTotalCost = autoPartsCost;
                            if (modalRepairCost) {
                                modalRepairCost.value = currentTotalCost.toFixed(2);
                            }

                            // ส่วนแสดงรายการอะไหล่และปุ่มลบ [x]
                            const partsListContainer = finishRepairModal.querySelector('#modal_auto_parts_list');
                            if (partsListContainer) {
                                try {
                                    const parts = JSON.parse(autoPartsJsonStr || '[]');
                                    if (parts) {
                                        if (parts.length > 0) {
                                            partsListContainer.innerHTML = '';
                                            parts.forEach(p => {
                                                const itemDiv = document.createElement('div');
                                                itemDiv.className = 'd-flex justify-content-between align-items-center mb-2 p-2 rounded bg-white shadow-sm border-start border-success border-3';
                                                itemDiv.innerHTML = `


                                                        ${p.name} (${p.code})

                                                        จำนวน ${parseInt(p.qty)} ${p.uom} [ล็อต: ${p.lot}] - ราคา ${(p.price * p.qty).toLocaleString()} บาท




                                                `;
                                                partsListContainer.appendChild(itemDiv);
                                            });

                                            // ตั้งเหตุการณ์คลิกสำหรับการลบอะไหล่พร้อมการยืนยันและคืนสต็อกทันที (Real-time Stock Return)
                                            const deleteButtons = partsListContainer.querySelectorAll('.delete-part-btn');
                                            deleteButtons.forEach(delBtn => {
                                                delBtn.addEventListener('click', function() {
                                                    const mId = this.getAttribute('data-id');
                                                    const parentElement = this.closest('.d-flex');

                                                    // แสดงหน้าต่างป๊อปอัปยืนยันการยกเลิกการใช้อะไหล่และคืนสต็อก
                                                    if (confirm("คุณต้องการยกเลิกการใช้อะไหล่รายการนี้และคืนสต็อกใช่หรือไม่?")) {
                                                        // ส่งคำขอไปยัง Backend เพื่อลบข้อมูลการเบิกและคืนสต็อกทันที
                                                        fetch('/automotive/repair/parts/delete_item', {
                                                            method: 'POST',
                                                            headers: {
                                                                'Content-Type': 'application/json',
                                                            },
                                                            body: JSON.stringify({
                                                                jsonrpc: '2.0',
                                                                params: {
                                                                    movement_id: parseInt(mId)
                                                                }
                                                            })
                                                        })
                                                        .then(response => response.json())
                                                        .then(data => {
                                                            if (data.result && data.result.success) {
                                                                // ลบรายการออกจาก DOM ทันที
                                                                parentElement.remove();

                                                                // อัปเดตราคารวมอะไหล่ในหน้าจอ
                                                                currentTotalCost = parseFloat(data.result.auto_parts_cost || 0);
                                                                if (modalRepairCost) {
                                                                    modalRepairCost.value = currentTotalCost.toFixed(2);
                                                                }

                                                                // อัปเดตข้อมูลรายละเอียด (metadata) บนปุ่มต้นทางนอก Modal เพื่อป้องกันข้อมูลไม่สอดคล้อง
                                                                button.setAttribute('data-parts-cost', data.result.auto_parts_cost);
                                                                button.setAttribute('data-parts-json', data.result.auto_parts_json);
                                                                button.setAttribute('data-parts-used', data.result.auto_parts_used);

                                                                // แสดงข้อความแจ้งเตือนหากไม่มีอะไหล่คลังเหลืออยู่แล้ว
                                                                if (partsListContainer.children.length === 0) {
                                                                    partsListContainer.innerHTML = '
ไม่มีข้อมูลอะไหล่ที่เบิกจากคลัง';
                                                                }

                                                                alert("ระบบได้ทำการยกเลิกรายการเบิกและคืนอะไหล่กลับเข้าสต็อกเรียบร้อยแล้ว");
                                                            } else {
                                                                const errMsg = (data.result && data.result.error) ? data.result.error : 'เกิดข้อผิดพลาดจากระบบในการลบรายการ';
                                                                alert("ไม่สามารถดำเนินการได้: " + errMsg);
                                                            }
                                                        })
                                                        .catch(err => {
                                                            console.error('Error deleting parts:', err);
                                                            alert("เกิดข้อผิดพลาดในการติดต่อสื่อสารกับเซิร์ฟเวอร์");
                                                        });
                                                    }
                                                });
                                            });
                                        } else {
                                            partsListContainer.innerHTML = '
ไม่มีข้อมูลอะไหล่ที่เบิกจากคลัง';
                                        }
                                    } else {
                                        partsListContainer.innerHTML = '
ไม่มีข้อมูลอะไหล่ที่เบิกจากคลัง';
                                    }
                                } catch (e) {
                                    console.error('Error parsing auto parts json:', e);
                                    partsListContainer.innerHTML = '
ไม่มีข้อมูลอะไหล่ที่เบิกจากคลัง';
                                }
                            }

                            // ตั้งเหตุการณ์คลิกปุ่มบันทึกอะไหล่แบบแยกส่วน (AJAX)
                            const btnSaveParts = finishRepairModal.querySelector('#btn_save_parts');
                            if (btnSaveParts) {
                                // โคลนปุ่มเพื่อล้าง event listener เก่าป้องกันการซ้ำซ้อน
                                const newBtnSaveParts = btnSaveParts.cloneNode(true);
                                btnSaveParts.parentNode.replaceChild(newBtnSaveParts, btnSaveParts);

                                newBtnSaveParts.addEventListener('click', function() {
                                    const deletedIdsStr = modalDeletedMovementIds.value;
                                    const deletedIds = deletedIdsStr ? deletedIdsStr.split(',').map(Number) : [];

                                    if (deletedIds.length === 0) {
                                        if (modalPartsAlert) {
                                            modalPartsAlert.textContent = 'ไม่มีรายการอะไหล่ที่ถูกลบ';
                                            modalPartsAlert.className = 'small fw-bold text-warning';
                                            modalPartsAlert.style.display = 'inline-block';
                                            setTimeout(() => { modalPartsAlert.style.display = 'none'; }, 3000);
                                        }
                                        return;
                                    }

                                    newBtnSaveParts.disabled = true;

                                    // ส่ง AJAX ด้วย fetch ไปบันทึกในฐานข้อมูลและเปลี่ยนสถานะการเบิกอะไหล่
                                    fetch('/automotive/repair/parts/update', {
                                        method: 'POST',
                                        headers: {
                                            'Content-Type': 'application/json',
                                        },
                                        body: JSON.stringify({
                                            jsonrpc: '2.0',
                                            params: {
                                                repair_id: parseInt(repairId),
                                                deleted_movement_ids: deletedIds
                                            }
                                        })
                                    })
                                    .then(response => response.json())
                                    .then(data => {
                                        newBtnSaveParts.disabled = false;
                                        if (data.result) {
                                            if (data.result.success) {
                                                modalDeletedMovementIds.value = '';
                                                currentTotalCost = parseFloat(data.result.auto_parts_cost || 0);
                                                if (modalRepairCost) {
                                                    modalRepairCost.value = currentTotalCost.toFixed(2);
                                                }

                                                // อัปเดตข้อมูลบนปุ่มหลักนอก Modal
                                                button.setAttribute('data-parts-cost', data.result.auto_parts_cost);
                                                button.setAttribute('data-parts-json', data.result.auto_parts_json);
                                                button.setAttribute('data-parts-used', data.result.auto_parts_used);

                                                if (modalPartsAlert) {
                                                    modalPartsAlert.textContent = 'บันทึกและคืนสต็อกแล้ว!';
                                                    modalPartsAlert.className = 'small fw-bold text-success';
                                                    modalPartsAlert.style.display = 'inline-block';
                                                    setTimeout(() => { modalPartsAlert.style.display = 'none'; }, 4000);
                                                }
                                            } else {
                                                let errMsg = 'เกิดข้อผิดพลาดในการบันทึก';
                                                if (data.result.error) errMsg = data.result.error;
                                                if (modalPartsAlert) {
                                                    modalPartsAlert.textContent = errMsg;
                                                    modalPartsAlert.className = 'small fw-bold text-danger';
                                                    modalPartsAlert.style.display = 'inline-block';
                                                    setTimeout(() => { modalPartsAlert.style.display = 'none'; }, 4000);
                                                }
                                            }
                                        }
                                    })
                                    .catch(error => {
                                        newBtnSaveParts.disabled = false;
                                        console.error('AJAX Error:', error);
                                        if (modalPartsAlert) {
                                            modalPartsAlert.textContent = 'การเชื่อมต่อขัดข้อง';
                                            modalPartsAlert.className = 'small fw-bold text-danger';
                                            modalPartsAlert.style.display = 'inline-block';
                                            setTimeout(() => { modalPartsAlert.style.display = 'none'; }, 4000);
                                        }
                                    });
                                });
                            }
                        });
                    }
                });

template.script:
document.addEventListener('DOMContentLoaded', function() {
    const modalTypeFilter = document.getElementById('modal_vehicle_type');
    const modalVehicleSelect = document.getElementById('modal_vehicle_id');

    if (modalTypeFilter && modalVehicleSelect) {
        const modalOpts = Array.from(modalVehicleSelect.options).slice(1);
        modalTypeFilter.addEventListener('change', function() {
            const sel = this.value;
            modalVehicleSelect.innerHTML = '-- เลือกรถ --';
            if (!sel) { modalVehicleSelect.disabled = true; return; }
            let count = 0;
            modalOpts.forEach(o => {
                if (o.getAttribute('data-type') === sel) {
                    modalVehicleSelect.appendChild(o.cloneNode(true));
                    count++;
                }
            });
            modalVehicleSelect.disabled = count === 0;
        });
    }
});

xpath.script:
function googleTranslateElementInit() {
    new google.translate.TranslateElement({
        pageLanguage: 'th',
        includedLanguages: 'th,en,my',
        autoDisplay: false
    }, 'google_translate_element');
}

// สคริปต์สั่งแปลอัตโนมัติเมื่อเปลี่ยนภาษา Odoo
(function() {
    var checkGoogleTranslate = setInterval(function() {
        var combo = document.querySelector('.goog-te-combo');
        if (combo) {
            clearInterval(checkGoogleTranslate);
            var currentLang = document.documentElement.lang.split('-')[0]; // 'th' or 'en' or 'my'

            // ถ้าไม่ใช่ภาษาไทย ให้สั่ง Google Translate ทำงาน
            if (currentLang && currentLang !== 'th') {
                combo.value = currentLang;
                combo.dispatchEvent(new Event('change'));
            }
        }
    }, 500);

    // ลบแถบ Google Top Bar ที่อาจจะโผล่มาทับหน้าเว็บ
    var style = document.createElement('style');
    style.innerHTML = 'body { top: 0 !important; } .goog-te-banner-frame { display: none !important; } .goog-te-balloon-frame { display: none !important; } .goog-tooltip { display: none !important; } .goog-tooltip:hover { display: none !important; } .preview-cm { display: none !important; }';
    document.head.appendChild(style);
})();

div.script:
(function() {
    try {
        const jsonData = document.getElementById('lot_details_json_data').textContent;
        window.LOT_DETAILS = JSON.parse(jsonData || '{}');
    } catch (e) {
        console.error('Error parsing LOT_DETAILS:', e);
        window.LOT_DETAILS = {};
    }
})();

                                document.addEventListener('DOMContentLoaded', function() {
                                    const partSelect = document.getElementById('issue_part_select');
                                    const qtyInput = document.getElementById('issue_qty');
                                    const warning = document.getElementById('qty_warning');
                                    const submitBtn = document.getElementById('issue_submit_btn');

                                    const lotSelect = document.getElementById('issue_lot_select');
                                    const unitPriceInput = document.getElementById('issue_unit_price');
                                    // lotDataItems removed

                                    function checkStock() {
                                        const selected = partSelect.options[partSelect.selectedIndex];
                                        if (selected && selected.value) {
                                            const stock = parseFloat(selected.getAttribute('data-qty') || 0);
                                            const qty = parseFloat(qtyInput.value || 0);
                                            if (qty > stock) {
                                                warning.classList.remove('d-none');
                                                submitBtn.disabled = true;
                                            } else {
                                                warning.classList.add('d-none');
                                                submitBtn.disabled = false;
                                            }

                                            // กรองล็อต
                                            updateLots(selected.value);
                                        } else {
                                            if (lotSelect) {
                                                lotSelect.innerHTML = '-- เลือกล็อต --';
                                                lotSelect.disabled = true;
                                            }
                                        }
                                    }

                                    function updateLots(partId) {
                                        if (!lotSelect) return;
                                        lotSelect.innerHTML = '-- เลือกล็อต --';
                                        let found = false;
                                        const lotData = (window.LOT_DETAILS || {})[partId] || {};

                                        Object.keys(lotData).forEach(lotName => {
                                            const info = lotData[lotName];
                                            if (info.qty > 0) {
                                                const opt = document.createElement('option');
                                                opt.value = lotName;
                                                opt.textContent = `${lotName} (คงเหลือ: ${info.qty.toLocaleString()})`;
                                                opt.dataset.price = info.price;
                                                lotSelect.appendChild(opt);
                                                found = true;
                                            }
                                        });
                                        lotSelect.disabled = !found;
                                        if (!found) lotSelect.innerHTML = '-- ไม่มีข้อมูลล็อต --';
                                    }

                                    if (lotSelect) {
                                        lotSelect.addEventListener('change', function() {
                                            const opt = this.options[this.selectedIndex];
                                            if (opt && opt.dataset.price) {
                                                unitPriceInput.value = opt.dataset.price;
                                            } else {
                                                unitPriceInput.value = '';
                                            }
                                        });
                                    }

                                    if (partSelect) partSelect.addEventListener('change', checkStock);
                                    if (qtyInput) qtyInput.addEventListener('input', checkStock);

                                    // ระบบค้นหาอัตโนมัติ Auto Complete (แทนที่ Dropdown ดั้งเดิม) ใน Modal รับและเบิกอะไหล่
                                    const makeAutocomplete = (inputId, resultsId, selectId) => {
                                        const inputEl = document.getElementById(inputId);
                                        const resultsEl = document.getElementById(resultsId);
                                        const selectEl = document.getElementById(selectId);
                                        if (!inputEl || !resultsEl || !selectEl) return;

                                        // ดึงข้อมูลตัวเลือกทั้งหมดจาก select ที่ซ่อนอยู่มาเก็บไว้ใน Array เพื่อสืบค้นข้อมูล
                                        const optionsData = Array.from(selectEl.options)
                                            .filter(opt => opt.value !== "")
                                            .map(opt => ({
                                                id: opt.value,
                                                text: opt.textContent.trim()
                                            }));

                                        const showResults = (filterText = '') => {
                                            resultsEl.innerHTML = '';
                                            const normalizedFilter = filterText.toLowerCase().trim();

                                            // กรองรายการ
                                            const matches = optionsData.filter(item => 
                                                item.text.toLowerCase().includes(normalizedFilter)
                                            );

                                            if (matches.length === 0) {
                                                const noMatch = document.createElement('div');
                                                noMatch.className = 'dropdown-item text-muted small py-2 px-3';
                                                noMatch.textContent = 'ไม่พบข้อมูลอะไหล่';
                                                resultsEl.appendChild(noMatch);
                                            } else {
                                                matches.forEach(item => {
                                                    const btn = document.createElement('button');
                                                    btn.type = 'button';
                                                    btn.className = 'dropdown-item text-start py-2 px-3 w-100 border-0 bg-transparent';
                                                    btn.style.outline = 'none';
                                                    btn.textContent = item.text;
                                                    btn.addEventListener('click', () => {
                                                        // เมื่อคลิกเลือก: ตั้งค่าอินพุต คีย์ค่าลง select และสั่งยิงอีเวนต์ change
                                                        inputEl.value = item.text;
                                                        selectEl.value = item.id;
                                                        selectEl.dispatchEvent(new Event('change'));
                                                        resultsEl.style.display = 'none';
                                                    });
                                                    resultsEl.appendChild(btn);
                                                });
                                            }
                                            resultsEl.style.display = 'block';
                                        };

                                        // ดักจับการพิมพ์
                                        inputEl.addEventListener('input', function() {
                                            showResults(this.value);
                                            // หากพิมพ์แก้ข้อความ ให้รีเซ็ตค่า select ต้นทางชั่วคราว
                                            if (selectEl.value !== "") {
                                                selectEl.value = "";
                                                selectEl.dispatchEvent(new Event('change'));
                                            }
                                        });

                                        // เมื่อโฟกัส
                                        inputEl.addEventListener('focus', function() {
                                            showResults(this.value);
                                        });

                                        // ซ่อนกล่องเมื่อคลิกข้างนอก
                                        document.addEventListener('click', function(e) {
                                            if (e.target !== inputEl && e.target !== resultsEl && !resultsEl.contains(e.target)) {
                                                resultsEl.style.display = 'none';
                                                // หากไม่ได้เลือกอะไหล่จริง ให้ล้างข้อความออก
                                                if (selectEl.value === "") {
                                                    inputEl.value = "";
                                                }
                                            }
                                        });
                                    };

                                    // เริ่มต้นใช้งานระบบ Auto Complete
                                    makeAutocomplete('receive_part_autocomplete', 'receive_part_results', 'receive_part_select');
                                    makeAutocomplete('issue_part_autocomplete', 'issue_part_results', 'issue_part_select');

                                    // เพิ่มระบบกรองรถในหน้าเบิกอะไหล่
                                    const issueTypeFilter = document.getElementById('issue_vehicle_type');
                                    const issueVehicleSelect = document.getElementById('issue_vehicle_id');
                                    const issueRepairSelect = document.getElementById('issue_repair_id');

                                    if (issueTypeFilter && issueVehicleSelect) {
                                        const allIssueOptions = Array.from(issueVehicleSelect.options).slice(1);
                                        issueTypeFilter.addEventListener('change', function() {
                                            const selectedType = this.value;
                                            issueVehicleSelect.innerHTML = '-- ไม่ระบุ / ของส่วนกลาง --';

                                            allIssueOptions.forEach(opt => {
                                                if (!selectedType || opt.getAttribute('data-type') === selectedType) {
                                                    issueVehicleSelect.appendChild(opt.cloneNode(true));
                                                }
                                            });
                                        });

                                        // เพิ่มระบบดึงข้อมูลรถยนต์อัตโนมัติเมื่อเลือกเชื่อมโยงใบแจ้งซ่อม
                                        if (issueRepairSelect) {
                                            issueRepairSelect.addEventListener('change', function() {
                                                const selectedOpt = this.options[this.selectedIndex];
                                                if (selectedOpt && selectedOpt.value) {
                                                    const vId = selectedOpt.getAttribute('data-vehicle-id');
                                                    const vType = selectedOpt.getAttribute('data-vehicle-type');

                                                    // 1. ตั้งค่าประเภทรถและทริกเกอร์ให้กรองรายการรถยนต์
                                                    if (vType) {
                                                        issueTypeFilter.value = vType;
                                                        issueTypeFilter.dispatchEvent(new Event('change'));
                                                    }
                                                    // 2. เลือกคันรถที่ระบุในใบแจ้งซ่อม
                                                    if (vId) {
                                                        issueVehicleSelect.value = vId;
                                                    }
                                                } else {
                                                    // หากไม่เลือกใบแจ้งซ่อม ให้คืนค่าเริ่มต้นทั้งหมด
                                                    issueTypeFilter.value = "";
                                                    issueTypeFilter.dispatchEvent(new Event('change'));
                                                    issueVehicleSelect.value = "";
                                                }
                                            });
                                        }
                                    }

                                    // ระบบ Modal แสดงรายละเอียดแยกตามล็อต (อ่านจาก JSON window.LOT_DETAILS)
                                    const sparePartRows = document.querySelectorAll('.spare-part-row');
                                    const modalLotBody = document.getElementById('modal_lot_body');
                                    const modalPartName = document.getElementById('modal_part_name');
                                    const modalTotalVal = document.getElementById('modal_total_val');
                                    const detailModal = document.getElementById('partLotDetailModal');

                                    // เก็บ row ที่คลิกล่าสุดเพื่อส่งให้ show.bs.modal
                                    let lastClickedRow = null;

                                    function populateModal(row) {
                                        if (!row) return;
                                        const partId = String(row.getAttribute('data-id') || '').trim();
                                        if (!partId) return;

                                        // ดึงชื่ออะไหล่จากหลายแหล่ง
                                        let partName = (row.getAttribute('data-name') || '').trim();
                                        if (!partName || partName === '---') {
                                            const nameEl = row.querySelector('.fw-semibold');
                                            if (nameEl) {
                                                partName = nameEl.textContent.trim();
                                            } else {
                                                const secondCell = row.cells ? row.cells[1] : null;
                                                partName = secondCell ? secondCell.textContent.trim() : 'ไม่พบชื่ออะไหล่';
                                            }
                                        }

                                        modalPartName.textContent = partName || '---';
                                        modalLotBody.innerHTML = '';
                                        let grandTotal = 0;
                                        let foundCount = 0;

                                        const allLotDetails = window.LOT_DETAILS || {};
                                        const lotData = allLotDetails[partId] || {};

                                        Object.keys(lotData).forEach(function(lotName) {
                                            const info = lotData[lotName];
                                            const qty = parseFloat(info.qty || 0);
                                            const price = parseFloat(info.price || 0);
                                            const total = qty * price;
                                            grandTotal += total;
                                            foundCount++;

                                            const tr = document.createElement('tr');
                                            const qtyBadge = qty > 0 ? 'bg-success' : 'bg-secondary';
                                            // ดึงข้อมูลวันที่นำเข้าของล็อตอะไหล่นี้
                                            const inDate = info.in_date || '-';
                                            tr.innerHTML =
                                                '' + lotName + '' +
                                                '' + inDate + '' +
                                                '' + qty.toLocaleString() + '' +
                                                '฿ ' + price.toLocaleString(undefined,{minimumFractionDigits:2}) + '' +
                                                '฿ ' + total.toLocaleString(undefined,{minimumFractionDigits:2}) + '';
                                            modalLotBody.appendChild(tr);
                                        });

                                        modalTotalVal.textContent = '฿ ' + grandTotal.toLocaleString(undefined,{minimumFractionDigits:2});
                                        if (foundCount === 0) {
                                            // ปรับแก้ colspan จากเดิม 4 คอลัมน์เป็น 5 คอลัมน์ให้เหมาะสมกับที่เพิ่มคอลัมน์วันที่
                                            modalLotBody.innerHTML = '
ยังไม่มีข้อมูลล็อตสำหรับอะไหล่ชิ้นนี้';
                                        }
                                    }

                                    // เก็บ row ที่คลิกล่าสุดไว้ใน lastClickedRow
                                    sparePartRows.forEach(function(row) {
                                        row.addEventListener('click', function() {
                                            lastClickedRow = this;
                                        });
                                    });

                                    // ใช้ show.bs.modal เป็น primary handler
                                    if (detailModal) {
                                        detailModal.addEventListener('show.bs.modal', function (event) {
                                            const triggerEl = event.relatedTarget || lastClickedRow;
                                            if (triggerEl) {
                                                populateModal(triggerEl);
                                            }
                                            lastClickedRow = null;
                                        });
                                    }
                                    // ระบบ Modal แก้ไขข้อมูลอะไหล่
                                    const editButtons = document.querySelectorAll('.edit-part-btn');
                                    const editModalEl = document.getElementById('editPartModal');
                                    const editModal = editModalEl ? new bootstrap.Modal(editModalEl) : null;

                                    editButtons.forEach(btn => {
                                        btn.addEventListener('click', function(e) {
                                            e.stopPropagation();
                                            if (editModal) {
                                                document.getElementById('edit_part_id').value = this.dataset.id;
                                                document.getElementById('edit_part_name').value = this.dataset.name;
                                                document.getElementById('edit_part_code').value = this.dataset.code || '';
                                                document.getElementById('edit_part_uom').value = this.dataset.uom || 'ชิ้น';
                                                document.getElementById('edit_part_min_qty').value = this.dataset.min_qty || '1.0';
                                                document.getElementById('edit_part_description').value = this.dataset.description || '';
                                                editModal.show();
                                            }
                                        });
                                    });
                                    });

document.addEventListener('DOMContentLoaded', function() {
    const histTypeFilter = document.getElementById('hist_vehicle_type');
    const histVehicleSelect = document.getElementById('hist_vehicle_id');

    if (histTypeFilter && histVehicleSelect) {
        const allHistOptions = Array.from(histVehicleSelect.options).slice(1);
        histTypeFilter.addEventListener('change', function() {
            const selectedType = this.value;
            histVehicleSelect.innerHTML = '-- ทั้งหมด --';

            allHistOptions.forEach(opt => {
                if (selectedType === 'all' || opt.getAttribute('data-type') === selectedType) {
                    histVehicleSelect.appendChild(opt.cloneNode(true));
                }
            });
        });
    }
});

                    document.addEventListener('DOMContentLoaded', function() {
                        const histTypeFilter = document.getElementById('hist_repair_type');
                        const histVehicleSelect = document.getElementById('hist_repair_vehicle_id');

                        // ระบบคัดกรองรถใน dropdown ตามประเภทของรถที่เลือก (ป้องกันการใช้ && ใน Odoo QWeb)
                        if (histTypeFilter) {
                            if (histVehicleSelect) {
                                const allHistOptions = Array.from(histVehicleSelect.options).slice(1);
                                histTypeFilter.addEventListener('change', function() {
                                    const selectedType = this.value;
                                    histVehicleSelect.innerHTML = '-- ทั้งหมด --';

                                    allHistOptions.forEach(opt => {
                                        if (!selectedType || opt.getAttribute('data-type') === selectedType) {
                                            histVehicleSelect.appendChild(opt.cloneNode(true));
                                        }
                                    });
                                });
                            }
                        }

                        // ระบบการดึงและแสดงข้อมูลรายละเอียดใน Modal เมื่อมีคลิกที่แถวประวัติการซ่อมบำรุง
                        const detailModal = document.getElementById('repairDetailModal');
                        if (detailModal) {
                            detailModal.addEventListener('show.bs.modal', function(event) {
                                const row = event.relatedTarget;
                                if (row) {
                                    // ดึงค่าทั้งหมดออกจาก attributes ของแถวตารางที่คลิก
                                    const name = row.getAttribute('data-name');
                                    const vehicle = row.getAttribute('data-vehicle');
                                    const plate = row.getAttribute('data-plate');
                                    const factory = row.getAttribute('data-factory');
                                    const reportDate = row.getAttribute('data-report-date');
                                    const finishDate = row.getAttribute('data-finish-date');
                                    const reporter = row.getAttribute('data-reporter');
                                    const description = row.getAttribute('data-description');
                                    const repairDetails = row.getAttribute('data-repair-details');
                                    const autoPartsUsed = row.getAttribute('data-auto-parts-used');
                                    const nonStockPartsText = row.getAttribute('data-non-stock-parts');
                                    const autoPartsCost = parseFloat(row.getAttribute('data-auto-parts-cost') || 0);
                                    const additionalCost = parseFloat(row.getAttribute('data-additional-cost') || 0);
                                    const totalCost = parseFloat(row.getAttribute('data-total-cost') || 0);
                                    const state = row.getAttribute('data-state');

                                    // ป้อนข้อมูลลงในสแปนหรือดิฟใน Modal
                                    detailModal.querySelector('#modalRepairName').textContent = name || '';
                                    detailModal.querySelector('#modalRepairVehicle').textContent = (vehicle ? vehicle : '') + (plate ? ' [' + plate + ']' : '');

                                    // ป้อนข้อมูลโรงงาน (Factory Badge) และเปลี่ยนสไตล์ตามสีโรงงาน
                                    const factoryBadge = detailModal.querySelector('#modalRepairFactory');
                                    if (factoryBadge) {
                                        factoryBadge.textContent = factory || '';
                                        factoryBadge.className = 'badge ms-2';
                                        if (factory === 'TQS') {
                                            factoryBadge.style.backgroundColor = '#16a34a';
                                            factoryBadge.style.color = 'white';
                                        } else if (factory === 'CKR') {
                                            factoryBadge.style.backgroundColor = '#880808';
                                            factoryBadge.style.color = 'white';
                                        } else if (factory === 'TPS') {
                                            factoryBadge.style.backgroundColor = '#d97706';
                                            factoryBadge.style.color = 'white';
                                        } else {
                                            factoryBadge.classList.add('bg-secondary');
                                        }
                                    }

                                    detailModal.querySelector('#modalRepairReporter').textContent = reporter || 'ระบบอัตโนมัติ';
                                    detailModal.querySelector('#modalRepairReportDate').textContent = reportDate || '-';
                                    detailModal.querySelector('#modalRepairFinishDate').textContent = finishDate || '-';

                                    // ดึงและแสดงผลระยะเวลาที่ใช้ในการซ่อมบำรุง
                                    const repairDuration = row.getAttribute('data-repair-duration');
                                    const durationEl = detailModal.querySelector('#modalRepairDuration');
                                    if (durationEl) {
                                        durationEl.innerHTML = '' + (repairDuration || '-');
                                    }

                                    detailModal.querySelector('#modalRepairDescription').textContent = description || '-';
                                    detailModal.querySelector('#modalRepairDetails').textContent = repairDetails || '-';

                                    // จัดเรียงและแสดงผลข้อมูลอะไหล่คลังระบบให้สวยงามพรีเมียม
                                    const formatAutoPartsHTML = (partsText) => {
                                        const fallback = `
ไม่มีการเบิกอะไหล่จากคลังระบบ`;
                                        if (!partsText || !partsText.trim()) return fallback;

                                        const lines = partsText.split('\n').map(l => l.trim()).filter(l => l.length > 0);
                                        if (lines.length === 0) return fallback;

                                        let html = '
';
                                        // ใช้ Regular Expression ในการแยกรายละเอียด: ชื่อ, รหัส, จำนวน, หน่วยนับ, ล็อต
                                        const regex = /^-\s*(.+?)\s*\((.+?)\)\s+จำนวน\s+(\d+)\s+(.+?)\s*\[ล็อต:\s*(.+?)\]$/;

                                        lines.forEach(line => {
                                            const match = line.match(regex);
                                            if (match) {
                                                const name = match[1];
                                                const code = match[2];
                                                const qty = match[3];
                                                const uom = match[4];
                                                const lot = match[5];

                                                html += `




                                                            ${name}
                                                            รหัส: ${code} | ล็อต: ${lot}



                                                            ${qty} ${uom}


                                                `;
                                            } else {
                                                // กรณีไม่เข้า regex ให้จัดแสดงผลแบบยืดหยุ่นธรรมดา
                                                let clean = line;
                                                if (clean.startsWith('- ')) clean = clean.substring(2);
                                                html += `


                                                        ${clean}

                                                `;
                                            }
                                        });
                                        html += '';
                                        return html;
                                    };

                                    // จัดเรียงและแสดงผลข้อมูลอะไหล่นอกคลังให้สวยงามพรีเมียม
                                    const formatNonStockPartsHTML = (partsText) => {
                                        const fallback = `
ไม่มีรายการอะไหล่นอกสต๊อก`;
                                        if (!partsText || !partsText.trim()) return fallback;

                                        const lines = partsText.split('\n').map(l => l.trim()).filter(l => l.length > 0);
                                        if (lines.length === 0) return fallback;

                                        let html = '
';
                                        lines.forEach(line => {
                                            let clean = line;
                                            if (clean.startsWith('- ')) clean = clean.substring(2);

                                            html += `



                                                    ${clean}

                                            `;
                                        });
                                        html += '';
                                        return html;
                                    };

                                    // เรนเดอร์ข้อมูลแบบโครงสร้าง HTML ลงใน Element
                                    const partsUsedEl = detailModal.querySelector('#modalRepairPartsUsed');
                                    if (partsUsedEl) {
                                        partsUsedEl.innerHTML = formatAutoPartsHTML(autoPartsUsed);
                                    }

                                    const nonStockEl = detailModal.querySelector('#modalRepairNonStockParts');
                                    if (nonStockEl) {
                                        nonStockEl.innerHTML = formatNonStockPartsHTML(nonStockPartsText);
                                    }

                                    // จัดรูปแบบการแสดงผลตัวเลขค่าใช้จ่าย
                                    const formatMoney = (val) => {
                                        return new Intl.NumberFormat('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(val);
                                    };

                                    // คำนวณยอดรวมสุทธิ (ราคารวมอะไหล่ระบบ + ค่าใช้จ่ายเพิ่มเติม)
                                    const calculatedTotal = autoPartsCost + additionalCost;

                                    detailModal.querySelector('#modalRepairAutoPartsCost').textContent = formatMoney(autoPartsCost);
                                    detailModal.querySelector('#modalRepairAdditionalCost').textContent = formatMoney(additionalCost);
                                    detailModal.querySelector('#modalRepairTotalCost').textContent = formatMoney(calculatedTotal);

                                    // เปลี่ยนสีสถานะใบแจ้งซ่อมตามประเภทสถานะ
                                    const stateBadge = detailModal.querySelector('#modalRepairState');
                                    if (stateBadge) {
                                        stateBadge.className = 'badge rounded-pill ms-2 px-3 py-1.5 fs-6';
                                        if (state === 'repairing') {
                                            stateBadge.textContent = 'กำลังซ่อม';
                                            stateBadge.className += ' bg-danger text-white';
                                        } else if (state === 'done') {
                                            stateBadge.textContent = 'เสร็จสิ้น';
                                            stateBadge.className += ' bg-success text-white';
                                        } else {
                                            stateBadge.textContent = 'ยกเลิก';
                                            stateBadge.className += ' bg-secondary text-white';
                                        }
                                    }
                                }
                            });
                        }
                    });
